        error.unhandled = true;
        if (rawError?.stack) {
          error.stack = rawError.stack;
        }
      }
      const hookResponse = await hook(error, event);
      if (hookResponse !== undefined) {
        return hookResponse;
      }
      throw error;
    }
  };
}

